package com.bank.tagnorm.service;

import java.util.logging.Logger;

// Min deletions to palindrome = length - longest palindromic subsequence.
public class TagNormalizeService {
    private static final Logger log = Logger.getLogger(TagNormalizeService.class.getName());

    public int minDeletions(String tag) {
        int n = tag.length();
        int[][] dp = new int[n][n];                 // longest palindromic subsequence table
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                if (tag.charAt(i) == tag.charAt(j))
                    dp[i][j] = 2 + dp[i + 1][j - 1]; // keep both ends
                else
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
        int lps = n == 0 ? 0 : dp[0][n - 1];
        final int r = n - lps;                      // delete everything not in the core
        log.info(() -> "Min deletions to make " + tag + " a palindrome = " + r);
        return r;
    }
}
