package com.bank.tagnorm;

import com.bank.tagnorm.service.TagNormalizeService;
import java.util.logging.Logger;

public class TagNormalizeApplication {
    private static final Logger log = Logger.getLogger(TagNormalizeApplication.class.getName());

    public static void main(String[] args) {
        TagNormalizeService service = new TagNormalizeService();
        String tag = "ABCDBA";
        int deletions = service.minDeletions(tag);
        log.info("Deletions to canonicalise tag " + tag + " is " + deletions);
    }
}
